CREATE DATABASE IF NOT EXISTS smart_study_planner CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE smart_study_planner;
CREATE TABLE Student (StudentID INT AUTO_INCREMENT PRIMARY KEY, FullName VARCHAR(120) NOT NULL, Email VARCHAR(255) NOT NULL UNIQUE, Password VARCHAR(255) NOT NULL, Level VARCHAR(40) NOT NULL, Programme VARCHAR(120) NOT NULL, StudyPreference VARCHAR(80), available_study_hours FLOAT DEFAULT 2, previous_grade FLOAT DEFAULT 50, attendance_rate FLOAT NULL, study_habit_score FLOAT DEFAULT 5, DateCreated DATETIME DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE Course (CourseID INT AUTO_INCREMENT PRIMARY KEY, StudentID INT NOT NULL, CourseCode VARCHAR(20) NOT NULL, CourseTitle VARCHAR(160) NOT NULL, CreditUnit INT NOT NULL, Semester VARCHAR(30) NOT NULL, description TEXT, difficulty INT DEFAULT 3, examination_date DATETIME NULL, CONSTRAINT fk_course_student FOREIGN KEY(StudentID) REFERENCES Student(StudentID) ON DELETE CASCADE, UNIQUE(StudentID,CourseCode), CHECK(difficulty BETWEEN 1 AND 5));
CREATE TABLE Assignment (AssignmentID INT AUTO_INCREMENT PRIMARY KEY, CourseID INT NOT NULL, StudentID INT NOT NULL, Title VARCHAR(160) NOT NULL, Description TEXT, DueDate DATETIME NOT NULL, Weight FLOAT DEFAULT 10, Status VARCHAR(20) DEFAULT 'pending', CompletedAt DATETIME NULL, FOREIGN KEY(CourseID) REFERENCES Course(CourseID) ON DELETE CASCADE, FOREIGN KEY(StudentID) REFERENCES Student(StudentID) ON DELETE CASCADE, CHECK(Status IN ('pending','completed')));
CREATE TABLE StudySchedule (ScheduleID INT AUTO_INCREMENT PRIMARY KEY, StudentID INT NOT NULL, course_id INT NULL, assignment_id INT NULL, StudyDate DATE NOT NULL, StartTime TIME NOT NULL, EndTime TIME NOT NULL, Duration INT NOT NULL, Topic VARCHAR(200) NOT NULL, Status VARCHAR(20) DEFAULT 'pending', FOREIGN KEY(StudentID) REFERENCES Student(StudentID) ON DELETE CASCADE, FOREIGN KEY(course_id) REFERENCES Course(CourseID) ON DELETE CASCADE, FOREIGN KEY(assignment_id) REFERENCES Assignment(AssignmentID) ON DELETE SET NULL);
CREATE TABLE FocusSession (FocusSessionID INT AUTO_INCREMENT PRIMARY KEY, StudentID INT NOT NULL, CourseID INT NULL, AssignmentID INT NULL, ScheduleID INT NULL, DurationMinutes INT NOT NULL, StartedAt DATETIME NOT NULL, CompletedAt DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, Mode VARCHAR(30) DEFAULT 'pomodoro', Status VARCHAR(20) DEFAULT 'completed', FOREIGN KEY(StudentID) REFERENCES Student(StudentID) ON DELETE CASCADE, FOREIGN KEY(CourseID) REFERENCES Course(CourseID) ON DELETE SET NULL, FOREIGN KEY(AssignmentID) REFERENCES Assignment(AssignmentID) ON DELETE SET NULL, FOREIGN KEY(ScheduleID) REFERENCES StudySchedule(ScheduleID) ON DELETE SET NULL);
CREATE TABLE Prediction (PredictionID INT AUTO_INCREMENT PRIMARY KEY, StudentID INT NOT NULL, CourseID INT NULL COMMENT 'Required by the API for all new course-specific predictions; nullable only for legacy rows', PredictedGrade FLOAT NOT NULL COMMENT 'Legacy compatibility: OULAD success probability percentage', PredictedOutcome VARCHAR(30), SuccessProbability FLOAT, ConfidenceScore FLOAT NOT NULL, risk_level VARCHAR(20) NOT NULL, ModelVersion VARCHAR(80), ObservationWindowDays INT DEFAULT 60, InputSnapshot TEXT, PredictionDate DATETIME DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(StudentID) REFERENCES Student(StudentID) ON DELETE CASCADE, FOREIGN KEY(CourseID) REFERENCES Course(CourseID) ON DELETE SET NULL);
CREATE TABLE Recommendation (RecommendationID INT AUTO_INCREMENT PRIMARY KEY, StudentID INT NOT NULL, PredictionID INT NOT NULL, recommendation_type VARCHAR(40), RecommendationText TEXT NOT NULL, PriorityLevel VARCHAR(20) NOT NULL, FOREIGN KEY(StudentID) REFERENCES Student(StudentID) ON DELETE CASCADE, FOREIGN KEY(PredictionID) REFERENCES Prediction(PredictionID) ON DELETE CASCADE);
CREATE TABLE Notification (NotificationID INT AUTO_INCREMENT PRIMARY KEY, StudentID INT NOT NULL, Message VARCHAR(255) NOT NULL, NotificationType VARCHAR(30) NOT NULL, Status VARCHAR(20) DEFAULT 'unread', DateSent DATETIME DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(StudentID) REFERENCES Student(StudentID) ON DELETE CASCADE);
CREATE TABLE Administrator (AdminID INT AUTO_INCREMENT PRIMARY KEY, FullName VARCHAR(120) NOT NULL, Username VARCHAR(80) NOT NULL UNIQUE, Password VARCHAR(255) NOT NULL, Role VARCHAR(30) DEFAULT 'administrator');
